example.snippet:
package main

import (
	"context"
	"fmt"
)

type Example struct{}

func (m *Example) Foo(ctx context.Context, bar int) (string, error) {
	return fmt.Sprintf("number is: %d", bar), nil
}

import { func, object } from "@dagger.io/dagger"

export interface Fooer {
  // You can also declare it as a method signature (e.g., `foo(): Promise`)
  foo: (bar: number) => Promise
}

@object()
export class Example {
  @func()
  async foo(bar: number): Promise {
    return `number is: ${bar}`
  }
}
